###############################################################
## Extract all possible 5mers from RNA
###############################################################

extract_5mers <- function(rna)
{

    n <- nchar(rna)


    if(n < 5)
    {
        return(character(0))
    }


    kmers <- character()


    for(i in 1:(n-4))
    {

        kmer <- substr(
            rna,
            i,
            i+4
        )


        kmers <- c(
            kmers,
            kmer
        )

    }


    return(kmers)

}



###############################################################
## Expand sequence into individual 5mers
###############################################################

library <- data.frame(
    kmer=character(),
    score=numeric(),
    stringsAsFactors=FALSE
)



for(i in seq_len(nrow(data)))
{

    kmers <- extract_5mers(
        data$rna[i]
    )


    if(length(kmers)==0)
        next


    temp <- data.frame(
        kmer=kmers,
        score=data$score[i],
        stringsAsFactors=FALSE
    )


    library <- rbind(
        library,
        temp
    )

}



